import{R as o,a as t}from"./chunks/ResearchPapers.DPzj9poK.js";import{o as r,c as d,j as n,a as i,E as a,a0 as s}from"./chunks/framework.BXmxXpv-.js";const c={class:"research-page"},h=JSON.parse('{"title":"Research Directions","description":"Two research lines in sensing and edge–end systems, and endpoint and edge AI inference, connect affordable information acquisition with resource-constrained model execution.","frontmatter":{"title":"Research Directions","description":"Two research lines in sensing and edge–end systems, and endpoint and edge AI inference, connect affordable information acquisition with resource-constrained model execution.","aside":false},"headers":[],"relativePath":"research.md","filePath":"en/research.md","lastUpdated":1793689603000}'),l={name:"research.md"},f=Object.assign(l,{setup(u){return(m,e)=>(r(),d("div",null,[n("div",c,[e[0]||(e[0]=n("h1",{id:"research-directions",tabindex:"-1"},[i("Research Directions "),n("a",{class:"header-anchor",href:"#research-directions","aria-label":'Permalink to "Research Directions"'},"​")],-1)),e[1]||(e[1]=n("p",null,"From acquiring real-world information to running models on endpoint and edge devices, we study the computing, communication, and runtime support intelligent systems need to turn limited hardware and energy into useful task execution.",-1)),e[2]||(e[2]=n("h2",{id:"research-goal",tabindex:"-1"},[i("Research Goal "),n("a",{class:"header-anchor",href:"#research-goal","aria-label":'Permalink to "Research Goal"'},"​")],-1)),e[3]||(e[3]=n("p",null,"We aim to enable intelligent systems to acquire useful real-world information continuously and perform efficient inference close to where that information originates, helping people understand their surroundings, anticipate change, and make informed decisions and take action.",-1)),e[4]||(e[4]=n("p",null,"Our research follows two parallel lines. Sensing and edge–end systems address affordable information acquisition; endpoint and edge AI inference addresses model execution under computing, memory, and energy constraints. They examine system overhead in information input and model execution, and connect through complex sensing applications.",-1)),a(o,{lang:"en"}),e[5]||(e[5]=s('<h2 id="sensing-and-edge-end-systems" tabindex="-1">Sensing and Edge–End Systems <a class="header-anchor" href="#sensing-and-edge-end-systems" aria-label="Permalink to &quot;Sensing and Edge–End Systems {#sensing-and-edge-end-systems}&quot;">​</a></h2><p>For sensing deployments with many long-running nodes, we study how functions are distributed across devices, nearby nodes, and gateways to reduce the total cost of acquiring useful information.</p><h3 id="microcomputing" tabindex="-1">Microcomputing <a class="header-anchor" href="#microcomputing" aria-label="Permalink to &quot;Microcomputing&quot;">​</a></h3><p><strong>Give lightweight, repetitive sensing tasks more direct execution paths.</strong> Register access, periodic sampling, and basic processing may involve little useful work, yet general-purpose control, peripheral adaptation, and wireless interaction can still impose substantial costs at every node. We study how to retain necessary local capabilities while sharing suitable support through gateways or nearby nodes.</p><ul><li><strong>Connect directly to peripherals.</strong> Radio-to-bus conversion links wireless signaling to peripheral operations.</li><li><strong>Separate adaptation from execution.</strong> Composable operations describe heterogeneous devices; configuration connects tasks to endpoint hardware.</li><li><strong>Choose execution granularity.</strong> Execute consecutive operations locally and share processors across nearby nodes to reduce repeated control and wireless round trips.</li></ul><p>These works address different questions about interfaces, device adaptation, and execution placement, forming architectural choices for lightweight sensing.</p>',6)),a(t,{topic:"computing",lang:"en"}),e[6]||(e[6]=n("h3",{id:"microcommunication",tabindex:"-1"},[i("Microcommunication "),n("a",{class:"header-anchor",href:"#microcommunication","aria-label":'Permalink to "Microcommunication"'},"​")],-1)),e[7]||(e[7]=n("p",null,[n("strong",null,"Provide wireless communication with less endpoint circuitry and processing overhead."),i(" Beyond carrying data, radios must generate references, synchronize, sample, despread, and demodulate signals. We use resource differences between infrastructure and devices, combining collaborative references with analog and mixed-signal circuits to change how these operations are performed.")],-1)),e[8]||(e[8]=n("p",null,"From interference-resistant downlinks in Passive DSSS, to passive chirp despreading in μMote and LoRa reception in Sisyphus, we focus on signal-processing paths that constrained devices can afford. Design choices account for coverage, data rate, reliability, and infrastructure requirements.",-1)),a(t,{topic:"communication",lang:"en"}),e[9]||(e[9]=n("h3",{id:"energy-management",tabindex:"-1"},[i("Energy Management "),n("a",{class:"header-anchor",href:"#energy-management","aria-label":'Permalink to "Energy Management"'},"​")],-1)),e[10]||(e[10]=n("p",null,[n("strong",null,"Devote more of the available energy to useful tasks."),i(" Battery-free devices harvest energy from time-varying sources. Monitoring storage and deciding when to run also consume energy. We co-design energy-state sensing, management computation, and task initiation, investigating gateway-assisted management and hardware admission at the device.")],-1)),e[11]||(e[11]=n("p",null,"μMan addresses who performs power management; Hades addresses how hardware directly checks task-start conditions. They reduce management overhead at different levels, aligning execution with available energy.",-1)),a(t,{topic:"energy",lang:"en"}),e[12]||(e[12]=s('<h3 id="complex-sensing" tabindex="-1">Complex Sensing <a class="header-anchor" href="#complex-sensing" aria-label="Permalink to &quot;Complex Sensing&quot;">​</a></h3><p class="research-status">Ongoing research · From basic physical measurements to audio, images, and video</p><p><strong>Determine early what a task needs to retain, process, and transmit.</strong> Audio and video provide richer environmental information while increasing sampling, storage, computing, and communication demands. We connect front-end information organization with endpoint execution through three complementary paths:</p><ul><li><strong>Audio and event-driven processing.</strong> Explore spiking neural networks (SNNs) with energy-aware control, organizing continuous signal processing around events and task needs.</li><li><strong>Visual structure and task evidence.</strong> Sensor-to-Semantics (S2S) studies representations of primitives, local structure, and their relationships. Downstream systems use evidence as needed and request additional images or regions when information is insufficient.</li><li><strong>Configurable computation and datapaths.</strong> Match regular, repetitive front-end processing to simplified computing arrays and specialized reconfigurable execution, addressing control and data-movement overhead together.</li></ul><p>Task outcomes assess the impact of information selection, while end-to-end evaluation determines whether front-end processing actually reduces downstream computation and transmission. The published works below illustrate configurable execution and task-aware visual sampling.</p>',5)),a(t,{topic:"sensing",lang:"en"}),e[13]||(e[13]=s('<h2 id="endpoint-and-edge-ai-inference" tabindex="-1">Endpoint and Edge AI Inference <a class="header-anchor" href="#endpoint-and-edge-ai-inference" aria-label="Permalink to &quot;Endpoint and Edge AI Inference {#endpoint-and-edge-ai-inference}&quot;">​</a></h2><p class="research-status">Ongoing research</p><p><strong>Run AI models efficiently on resource-constrained platforms.</strong> For endpoint and edge devices, we study how to reduce the computing, memory, and energy overhead of inference while meeting task-quality and response requirements, enabling models to serve practical systems.</p><p>This direction examines operator computation, data movement, memory use, and execution partitioning between devices and edge resources. We start from bottlenecks in concrete models and platforms to identify execution approaches suited to the task.</p><p>Complex sensing connects the two research lines: sensing front ends organize task-relevant information and evidence, while inference systems execute downstream models. Together, they determine the quality and overhead of the path from information input to task output.</p><h2 id="security-and-information-applications" tabindex="-1">Security and Information Applications <a class="header-anchor" href="#security-and-information-applications" aria-label="Permalink to &quot;Security and Information Applications&quot;">​</a></h2><p>Practical sensing systems also require trustworthy acquisition and interaction, together with efficient data analysis. Our work covers privacy protection in wireless and physical sensing, user authentication, streaming graph computation, recommendation, and multi-source information processing, with applications in wearables, environmental monitoring, and data-driven systems.</p>',7)),a(t,{topic:"applications",lang:"en"}),e[14]||(e[14]=n("p",null,"We evaluate information quality, response time, energy use, and deployment cost in concrete scenarios, connecting advances in devices, communication, computing, and applications to sustained, reliable sensing.",-1)),e[15]||(e[15]=n("p",null,[n("a",{href:"/publication"},"All selected publications"),i(" · "),n("a",{href:"/contact"},"Contact us")],-1))])]))}});export{h as __pageData,f as default};
